{"file_path":"./trinary.go","content":"// Package trinary converts trinary (base-3) number strings to decimal.
package trinary

import (
	"fmt"
	"math"
)

// ParseTrinary converts a trinary number string to its decimal (int64)
// equivalent. It returns an error if arg is not a valid trinary number or
// if the value overflows int64.
func ParseTrinary(arg string) (int64, error) {
	var result int64

	for _, r := range arg {
		var digit int64
		switch r {
		case '0':
			digit = 0
		case '1':
			digit = 1
		case '2':
			digit = 2
		default:
			return 0, fmt.Errorf("invalid trinary digit %q in %q", r, arg)
		}

		if result > (math.MaxInt64-digit)/3 {
			return 0, fmt.Errorf("trinary value %q overflows int64", arg)
		}

		result = result*3 + digit
	}

	if len(arg) == 0 {
		return 0, fmt.Errorf("empty trinary string")
	}

	return result, nil
}
"}

